    password = 'test_password'
    hash_password = hash_password(password)
    lookup_password = lookup_password(password, rainbow_table)
    if lookup_password is not None:
        print(f"The plaintext of the password '{password}' is '{lookup_password}'.")
    else:
        print("The plaintext of the password isn't found in the rainbow table.")

if __name__ == '__main__':
