using namespace std;

// 创建一个 SQLi 格式化函数
void sqlFormat(const string& sql, const string& dev_name) {
    string updated_sql;

    // 将 SQLi 代码替换为变量替换
    vector<string> variables = {"@dev_name"};
    for (int i = 0; i < sql.size(); ++i) {
        if (sql[i] == '?') {
            variables.push_back(sql.substr(i + 1, sql.size() - i - 1));
            i += 2; // 去掉 '?' 和 '?='
        }
    }

    // 将变量替换为相应的值
    for (auto& v : variables) {
        if (v == "@dev_name") {
            updated_sql += "dev_name";
        } else {
            updated_sql += v;
        }
    }

    // 将原始 SQLi 代码连接起来
    updated_sql.append(";");
    updated_sql.append(sql);
}

// 测试函数
int main() {
    string sql = "SELECT * FROM users WHERE dev_name = @dev_name";

    // 根据传入的 dev_name 进行 SQLi 替换
    sqlFormat(sql, "dev_name");

    // 打印替换后的 SQLi 代码
    cout << sql << endl;

    return 0;
}
